%dw 2.0
output application/json
---
payload map (o) -> do {
  var rows = o.items map { sku: $.sku, qty: $.qty, price: $.price }
  var csv = write(rows, "application/csv")
  var parsed = read(csv, "application/csv")
  ---
  {
    orderId: o.orderId,
    csv: csv,
    total: sum(parsed map ((r) -> (r.qty as Number) * (r.price as Number)))
  }
}

